// Add the near-field UI note to every locale catalog (zh-Hant is generated by npm run i18n -- --zh-hant).
import fs from 'node:fs';
const KEY = 'Nearby buildings and trees are generated by GEV from OpenStreetMap data';
const T = {
  ar: 'المباني والأشجار القريبة من إنشاء GEV استنادًا إلى بيانات OpenStreetMap',
  de: 'Gebäude und Bäume in der Nähe erzeugt GEV aus OpenStreetMap-Daten',
  es: 'GEV genera los edificios y árboles cercanos a partir de datos de OpenStreetMap',
  fr: 'Les bâtiments et arbres proches sont générés par GEV à partir des données OpenStreetMap',
  he: 'מבנים ועצים קרובים נוצרים על ידי GEV מנתוני OpenStreetMap',
  it: 'Edifici e alberi vicini sono generati da GEV dai dati OpenStreetMap',
  ja: '近くの建物と樹木は OpenStreetMap のデータから GEV が生成しています',
  pt: 'Os edifícios e árvores próximos são gerados pelo GEV a partir de dados do OpenStreetMap',
  ru: 'Ближайшие здания и деревья созданы GEV по данным OpenStreetMap',
  sv: 'Byggnader och träd i närheten genereras av GEV från OpenStreetMap-data',
  uk: 'Найближчі будівлі й дерева створено GEV за даними OpenStreetMap',
  'zh-CN': '附近的建筑和树木由 GEV 根据 OpenStreetMap 数据生成',
};
for (const [loc, text] of Object.entries(T)) {
  const file = `src/i18n/locales/${loc}.json`;
  const j = JSON.parse(fs.readFileSync(file, 'utf8'));
  j[KEY] = text;
  fs.writeFileSync(file, `${JSON.stringify(j, null, 2)}\n`);
}
